import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"隱私權政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1794112334000}'),t={name:"zh-TW/guide/privacy.md"};function o(s,a,h,n,c,p){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><h2 id="資料蒐集" tabindex="-1">資料蒐集 <a class="header-anchor" href="#資料蒐集" aria-label="Permalink to &quot;資料蒐集&quot;">​</a></h2><p>開發者不會透過本應用程式蒐集任何資料。</p><h3 id="我們不會蒐集的資訊" tabindex="-1">我們不會蒐集的資訊 <a class="header-anchor" href="#我們不會蒐集的資訊" aria-label="Permalink to &quot;我們不會蒐集的資訊&quot;">​</a></h3><ul><li>個人資訊</li><li>使用統計</li><li>裝置資訊</li><li>位置資料</li><li>圖片內容或中繼資料</li><li>瀏覽記錄</li><li>任何其他使用者資料</li></ul><h3 id="chrome-擴充功能" tabindex="-1">Chrome 擴充功能 <a class="header-anchor" href="#chrome-擴充功能" aria-label="Permalink to &quot;Chrome 擴充功能&quot;">​</a></h3><p>Nicasa Chrome 擴充功能僅為實現看圖功能而請求存取頁面內容以擷取圖片位址。該擴充功能：</p><ul><li>不會讀取或儲存瀏覽記錄</li><li>不會追蹤使用者行為</li><li>不會向外部伺服器傳輸任何資料</li><li>僅在瀏覽器本機處理圖片位址</li></ul><h3 id="本機處理" tabindex="-1">本機處理 <a class="header-anchor" href="#本機處理" aria-label="Permalink to &quot;本機處理&quot;">​</a></h3><p>所有圖片處理、編輯與檢視都在你的裝置本機完成，不會把圖片或資料上傳到外部伺服器。</p><h3 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to &quot;權限&quot;">​</a></h3><p>Nicasa 在 macOS 上請求以下權限：</p><ul><li><strong>螢幕錄製</strong>：截圖功能所必需</li><li><strong>輔助使用</strong>：選用，用於懸浮模式相關功能</li><li><strong>檔案與檔案夾</strong>：存取使用者選取的目錄以瀏覽圖片</li></ul><p>這些權限可在「系統設定 &gt; 隱私權與安全性」中管理。</p><h3 id="第三方服務" tabindex="-1">第三方服務 <a class="header-anchor" href="#第三方服務" aria-label="Permalink to &quot;第三方服務&quot;">​</a></h3><p>Nicasa 未整合任何第三方統計、廣告或資料蒐集服務。</p><h3 id="隱私選項" tabindex="-1">隱私選項 <a class="header-anchor" href="#隱私選項" aria-label="Permalink to &quot;隱私選項&quot;">​</a></h3><p>如果你想行使隱私權權利（例如：查閱、刪除、可攜或拒絕授權等請求），或你確信 Nicasa 持有關於你的個人資料，可透過以下任一方式提交請求：</p><ul><li>電子郵件：nicasa@w3cub.com</li><li>提交隱私 issue：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>使用我們的隱私選項頁面：/zh-TW/guide/privacy-choices</li></ul><p>由於如上所述 Nicasa 並不蒐集個人資料，許多請求會以「未持有任何個人資料」的確認作為回覆。如果未來的版本開始蒐集個人資料，本頁面與隱私選項表單將提供提交與追蹤請求的途徑。</p><p>我們力求在 30 天內回應合理的隱私請求。</p><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h3><p>本隱私權政策可能會隨應用程式新版本而更新。如有重大變更，我們會通知使用者。</p><h3 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h3><p>如對隱私權有疑問，請透過 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub 儲存庫</a>聯絡我們。</p>',25)])])}const m=i(t,[["render",o]]);export{d as __pageData,m as default};
